arguments.command:
python3 -c "
import parse

fmt = '''
            letters: {:w}
            non-letters: {:W}
            whitespace: \"{!s}\"
            non-whitespace: \\t{:S}\\n
            digits: {:d}
            non-digits: {:D}
            numbers with thousands: {:n}
            fixed-point: {:f}
            floating-point: {:e}
            general numbers: {:g} {:g}
            binary: {:b}
            octal: {:o}
            hex: {:x}
'''

print('Expression:')
p = parse.Parser(fmt)
print(repr(p._expression[:500]))
" 2>&1
